    ('payment', 'Cobranças e pagamentos', 'Pagamento real confirmado pelo backend. Mensagens repetidas não criam outro pagamento; valor recebido é fato.', 'Pagamento real verificado pelo backend. Identidade única por provedor impede duplicar o mesmo recebimento. Podem existir vários pagamentos reais da mesma cobrança. Verificação externa e conferência de valor não são feitas por CHECK.', 'Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('payment_application', 'Aplicação e reembolso', 'Um benefício recebe no máximo um pagamento. Criar/aplicar ciclo ou upgrade na mesma transação.', 'Um pagamento e uma ordem só podem ter uma aplicação. Aplicar benefício e criar/alterar ciclo na mesma transação. Validação de vigência, concorrência e incompatibilidade com reembolso depende das rotinas.', 'Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('payment_application_log', 'Auditoria', 'Histórico de payment_application, preenchido pelas rotinas de auditoria.', 'Snapshots tipados de payment_application. INSERT registra AFTER; DELETE registra BEFORE; UPDATE requer BEFORE e AFTER no mesmo evento. CHECKs validam formato, não geram registros. Colunas copiadas por LIKE não mantêm as FKs, UNIQUEs e CHECKs da origem. Colunas geradas viram valores históricos. Produção dos retratos depende das futuras triggers; não aplicar regras de estado atual ao retrato histórico.', 'REVOKE ALL FROM PUBLIC consta no script 01. Preenchimento reservado às futuras rotinas de auditoria; definir roles de leitura e execução. Privilégios do dono e grants diretos exigem revisão. Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('payment_log', 'Auditoria', 'Histórico de payment, preenchido pelas rotinas de auditoria.', 'Snapshots tipados de payment. INSERT registra AFTER; DELETE registra BEFORE; UPDATE requer BEFORE e AFTER no mesmo evento. CHECKs validam formato, não geram registros. Colunas copiadas por LIKE não mantêm as FKs, UNIQUEs e CHECKs da origem. Colunas geradas viram valores históricos. Produção dos retratos depende das futuras triggers; não aplicar regras de estado atual ao retrato histórico.', 'REVOKE ALL FROM PUBLIC consta no script 01. Preenchimento reservado às futuras rotinas de auditoria; definir roles de leitura e execução. Privilégios do dono e grants diretos exigem revisão. Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('payment_provider_event', 'Cobranças e pagamentos', 'Evento verificado do provedor. Sem payload bruto, dados de cartão, credenciais ou URLs de pagamento.', 'Evento do provedor deduplicado por provedor/ID do evento, distinto da deduplicação do pagamento. Processamento concluído exige data. Não armazena payload bruto, dados de cartão, credenciais ou URLs de pagamento. Autenticidade e reprocessamento são responsabilidades do backend.', 'Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('payment_refund', 'Aplicação e reembolso', 'Reembolso integral único por pagamento nos dois casos aprovados. Solicitação não significa conclusão.', 'Reembolso integral único por pagamento, com valor e provedor conferidos pela FK composta. Motivos previstos: DUPLICATE_BENEFIT e EXPIRED_UPGRADE. Solicitação não equivale a conclusão; confirmação e repetição idempotente dependem da integração.', 'Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('payment_refund_attempt', 'Aplicação e reembolso', 'Tentativas do mesmo reembolso, preservando uma chave idempotente no provedor. Não armazenar credenciais nas mensagens.', 'Tentativas numeradas e únicas por reembolso. Resultado e fim são registrados juntos. Repetição mantém a identidade do reembolso. Mensagens não devem conter credenciais.', 'Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('payment_refund_log', 'Auditoria', 'Histórico de payment_refund, preenchido pelas rotinas de auditoria.', 'Snapshots tipados de payment_refund. INSERT registra AFTER; DELETE registra BEFORE; UPDATE requer BEFORE e AFTER no mesmo evento. CHECKs validam formato, não geram registros. Colunas copiadas por LIKE não mantêm as FKs, UNIQUEs e CHECKs da origem. Colunas geradas viram valores históricos. Produção dos retratos depende das futuras triggers; não aplicar regras de estado atual ao retrato histórico.', 'REVOKE ALL FROM PUBLIC consta no script 01. Preenchimento reservado às futuras rotinas de auditoria; definir roles de leitura e execução. Privilégios do dono e grants diretos exigem revisão. Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('pev', 'PEVs e entregas B2C', 'Exatamente um responsável. Inativação preserva aprovação. Sincronizar is_pev na mesma transação.', 'Exatamente um responsável: cidadão ou estabelecimento. Cada responsável possui no máximo um PEV. Aprovação exige autor ADMIN e data. Aprovação operacional e autorização para registrar entregas dependem da API/rotinas.', 'Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('pev_log', 'Auditoria', 'Histórico de pev, preenchido pelas rotinas de auditoria.', 'Snapshots tipados de pev. INSERT registra AFTER; DELETE registra BEFORE; UPDATE requer BEFORE e AFTER no mesmo evento. CHECKs validam formato, não geram registros. Colunas copiadas por LIKE não mantêm as FKs, UNIQUEs e CHECKs da origem. Colunas geradas viram valores históricos. Produção dos retratos depende das futuras triggers; não aplicar regras de estado atual ao retrato histórico.', 'REVOKE ALL FROM PUBLIC consta no script 01. Preenchimento reservado às futuras rotinas de auditoria; definir roles de leitura e execução. Privilégios do dono e grants diretos exigem revisão. Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('point_calculation', 'Pontos e certificados', 'Revisão de cálculo por evento. Piso zero aplicado em sequência, não ao somatório final; preservar revisões anteriores.', 'Cada revisão pertence a coleta B2B OU entrega B2C, com no máximo uma revisão vigente por origem. Saldo posterior aplica piso zero a cada evento; não somente à soma final. Reconstrução preserva revisões e justifica autoria. Coerência com componentes e saldo do usuário depende de rotina.', 'Saldos e cálculos devem ser mantidos pelas rotinas transacionais; não oferecer edição livre de pontos na API. Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('point_calculation_log', 'Auditoria', 'Histórico de point_calculation, preenchido pelas rotinas de auditoria.', 'Snapshots tipados de point_calculation. INSERT registra AFTER; DELETE registra BEFORE; UPDATE requer BEFORE e AFTER no mesmo evento. CHECKs validam formato, não geram registros. Colunas copiadas por LIKE não mantêm as FKs, UNIQUEs e CHECKs da origem. Colunas geradas viram valores históricos. Produção dos retratos depende das futuras triggers; não aplicar regras de estado atual ao retrato histórico.', 'REVOKE ALL FROM PUBLIC consta no script 01. Preenchimento reservado às futuras rotinas de auditoria; definir roles de leitura e execução. Privilégios do dono e grants diretos exigem revisão. Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('point_transaction', 'Pontos e certificados', 'Componentes nominais de uma revisão: volume, sucesso, recorrência ou penalidade única. Sem ajuste manual livre.', 'Decompõe cálculo em componentes únicos: volume, bônus de sucesso +50, recorrência em múltiplos de 10 até 100, ou penalidade -50. CHECK limita cada componente; rotina confere soma e combinação correta. Não é tabela de ranking.', 'Saldos e cálculos devem ser mantidos pelas rotinas transacionais; não oferecer edição livre de pontos na API. Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('subscription_cycle', 'Planos e ciclos', 'Período pago [início,fim). Limites vigentes substituídos no upgrade. Sem contadores duplicados de consumo.', 'Período pago finito [starts_at, ends_at), sem sobreposição para o mesmo estabelecimento, garantido por EXCLUDE. Número único por assinatura. Upgrade substitui limites, sem somar franquias nem mudar datas. Disponibilidade e concorrência de reservas dependem de rotinas.', 'Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('subscription_cycle_change', 'Planos e ciclos', 'Histórico de upgrade pago: antes/depois dos limites. Não muda datas nem soma franquias.', 'Histórico de upgrade vinculado a aplicação UPGRADE do mesmo ciclo. Plano, preço e franquias aumentam; datas, consumo e reservas são preservados. Manutenção do histórico depende de rotina/permissões, não apenas das FKs.', 'Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('subscription_cycle_log', 'Auditoria', 'Histórico de subscription_cycle, preenchido pelas rotinas de auditoria.', 'Snapshots tipados de subscription_cycle. INSERT registra AFTER; DELETE registra BEFORE; UPDATE requer BEFORE e AFTER no mesmo evento. CHECKs validam formato, não geram registros. Colunas copiadas por LIKE não mantêm as FKs, UNIQUEs e CHECKs da origem. Colunas geradas viram valores históricos. Produção dos retratos depende das futuras triggers; não aplicar regras de estado atual ao retrato histórico.', 'REVOKE ALL FROM PUBLIC consta no script 01. Preenchimento reservado às futuras rotinas de auditoria; definir roles de leitura e execução. Privilégios do dono e grants diretos exigem revisão. Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('subscription_plan', 'Planos e ciclos', 'Catálogo comercial. Cobranças e ciclos mantêm cópias das condições contratadas.', 'Preço mensal, franquia de litros e limite de coletas positivos. Condições contratadas são copiadas para cobrança e ciclo; editar o catálogo não deve reescrever contratos anteriores.', 'Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('subscription_plan_log', 'Auditoria', 'Histórico de subscription_plan, preenchido pelas rotinas de auditoria.', 'Snapshots tipados de subscription_plan. INSERT registra AFTER; DELETE registra BEFORE; UPDATE requer BEFORE e AFTER no mesmo evento. CHECKs validam formato, não geram registros. Colunas copiadas por LIKE não mantêm as FKs, UNIQUEs e CHECKs da origem. Colunas geradas viram valores históricos. Produção dos retratos depende das futuras triggers; não aplicar regras de estado atual ao retrato histórico.', 'REVOKE ALL FROM PUBLIC consta no script 01. Preenchimento reservado às futuras rotinas de auditoria; definir roles de leitura e execução. Privilégios do dono e grants diretos exigem revisão. Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('telephone', 'Cadastros e identidade', 'Um número pode pertencer a vários usuários, sem repetição para o mesmo usuário.', 'O mesmo telefone pode pertencer a usuários diferentes; o par usuário/número não se repete. O tamanho permitido não comprova a validade do número.', 'Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('user_qr_code', 'Cadastros e identidade', 'Registro central do token vigente. Unicidade global B2C/B2B; sem histórico do conteúdo dos tokens.', 'Token vigente único globalmente entre B2B e B2C. A atualização propaga às especializações por FK ON UPDATE CASCADE. A auditoria não preserva o conteúdo do token.', 'Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('user_qr_code_log', 'Auditoria', 'Histórico de user_qr_code, preenchido pelas rotinas de auditoria.', 'Snapshots tipados de user_qr_code. INSERT registra AFTER; DELETE registra BEFORE; UPDATE requer BEFORE e AFTER no mesmo evento. CHECKs validam formato, não geram registros. Colunas copiadas por LIKE não mantêm as FKs, UNIQUEs e CHECKs da origem. Colunas geradas viram valores históricos. Produção dos retratos depende das futuras triggers; não aplicar regras de estado atual ao retrato histórico.', 'REVOKE ALL FROM PUBLIC consta no script 01. Preenchimento reservado às futuras rotinas de auditoria; definir roles de leitura e execução. Privilégios do dono e grants diretos exigem revisão. Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('users', 'Cadastros e identidade', 'Usuários autenticados. Driver não possui login. Inativar para preservar histórico.', 'Identidade autenticada com e-mail único e perfil restrito pelo enum. Motorista não é perfil de login. Validação de senha e autorização são responsabilidades da autenticação/API. A FK composta permite conferir perfil nas especializações.', 'Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('users_log', 'Auditoria', 'Histórico de users, preenchido pelas rotinas de auditoria.', 'Snapshots tipados de users. INSERT registra AFTER; DELETE registra BEFORE; UPDATE requer BEFORE e AFTER no mesmo evento. CHECKs validam formato, não geram registros. Colunas copiadas por LIKE não mantêm as FKs, UNIQUEs e CHECKs da origem. Colunas geradas viram valores históricos. Produção dos retratos depende das futuras triggers; não aplicar regras de estado atual ao retrato histórico.', 'REVOKE ALL FROM PUBLIC consta no script 01. Preenchimento reservado às futuras rotinas de auditoria; definir roles de leitura e execução. Privilégios do dono e grants diretos exigem revisão. Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'PENDING', '01_structure.sql; 02_check_constraints.sql; 03_indexes.sql — revisão local de 16/09/2026'),
    ('data_catalog_table', 'Governança de dados', 'Documentação de finalidade, regras e acesso das tabelas.', 'Identidade documental única por schema e tabela. Não cria a tabela documentada nem aplica a política descrita. Alterações no modelo exigem revisão do catálogo.', 'Catálogo sem dados reais. PUBLIC sem concessões explícitas neste módulo; definir responsáveis por manutenção e leitores autorizados.', 'PENDING', 'data_catalog/01_structure.sql; 02_check_constraints.sql'),
    ('data_catalog_column', 'Governança de dados', 'Documentação de significado e regras das colunas.', 'Uma coluna documental por tabela e nome. FK vincula à tabela do catálogo, não ao objeto físico. Objetos físicos removidos são sinalizados pela view e pelas consultas de validação, sem apagar a documentação.', 'Herdar política documental de data_catalog_table e definir mantenedores/leitores. Não armazenar valores reais.', 'PENDING', 'data_catalog/01_structure.sql; 02_check_constraints.sql')
)
INSERT INTO data_catalog_table
    (schema_name, table_name, domain_name, description, business_rules, access_policy, access_status, source_reference)
SELECT current_schema(), s.* FROM seed s
JOIN pg_catalog.pg_namespace n ON n.nspname = current_schema()
JOIN pg_catalog.pg_class c ON c.relnamespace = n.oid AND c.relname = s.table_name AND c.relkind IN ('r','p')
ON CONFLICT (schema_name, table_name) DO NOTHING;


-- A terceira tabela é um cadastro documental, não executa CREATE ROLE.
INSERT INTO data_catalog_role (role_name, description) VALUES
('olius_owner', 'Proprietário técnico dos objetos do OLIUS; responsável pela implantação e alteração estrutural. Não é a conta da API. O nome por si só não transfere propriedade.'),
('olius_reader', 'Consulta técnica às tabelas/colunas operacionais autorizadas e ao catálogo. Sem acesso automático a credenciais, tokens, integrações financeiras ou logs.'),
('olius_auditor', 'Consulta às 22 tabelas de auditoria e ao catálogo, sem escrita direta nos logs. Eventos e tentativas do provedor não são incluídos automaticamente.'),
('olius_catalog_editor', 'Manutenção documental: SELECT, INSERT, UPDATE e DELETE nas três tabelas do catálogo e SELECT na view; não administra roles PostgreSQL.'),
('olius_api', 'Conta técnica da aplicação: consultas necessárias, alterações cadastrais limitadas e execução de rotinas autorizadas; sem propriedade dos objetos ou escrita livre em saldos e logs. Lista exata de concessões depende das rotinas.')
ON CONFLICT (role_name) DO NOTHING;

INSERT INTO data_catalog_table
    (schema_name, table_name, domain_name, description, business_rules, access_policy, access_status, source_reference)
VALUES (current_schema(), 'data_catalog_role', 'Governança de dados',
    'Cadastro das roles técnicas do PostgreSQL e suas responsabilidades.',
    'Nome único; a view associa ao pg_roles pelo nome e informa ausência sem criar a role. PK identifica somente o registro documental.',
    'Política PostgreSQL aprovada: olius_reader e olius_auditor SELECT; olius_catalog_editor SELECT, INSERT, UPDATE, DELETE. API sem acesso por padrão. olius_owner administra o objeto. Leitura da view requer SELECT na view e nas três tabelas documentais.DEFINED indica política documentada, não implantação. A view identifica roles com privilégio de dados em access_status; grants e memberships precisam de implantação própria.', 'DEFINED', 'Política de roles aprovada em 17/09/2026')
ON CONFLICT (schema_name, table_name) DO NOTHING;

WITH seed(column_name, description) AS (VALUES
    ('id', 'PK do cadastro documental da role; não é o OID da role PostgreSQL.'),
    ('role_name', 'Nome exato e único usado para associar a documentação à role existente no servidor.'),
    ('description', 'Finalidade e responsabilidades aprovadas para a role técnica.')
)
INSERT INTO data_catalog_column (table_catalog_id, column_name, description, source_reference)
SELECT d.id, s.column_name, s.description, 'data_catalog/01_structure.sql; política de roles aprovada'
FROM seed s CROSS JOIN data_catalog_table d
WHERE d.schema_name = current_schema() AND d.table_name = 'data_catalog_role'
ON CONFLICT (table_catalog_id, column_name) DO NOTHING;

