WITH policies(table_name, previous_policy, approved_policy) AS (VALUES
('addresses', 'Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'Política PostgreSQL aprovada: olius_owner administra o objeto. olius_reader sem acesso à tabela inteira por padrão. olius_auditor e olius_catalog_editor sem concessão adicional nesta tabela. olius_api recebe apenas os privilégios necessários às operações autorizadas; concessões exatas devem ser fechadas com as assinaturas das rotinas e consultas da API. Sem DELETE livre para fatos operacionais/financeiros; sem escrita livre em saldos. DEFINED indica política documentada, não implantação. A view identifica roles com privilégio de dados em access_status; grants e memberships precisam de implantação própria.'),
('addresses_log', 'REVOKE ALL FROM PUBLIC consta no script 01. Preenchimento reservado às futuras rotinas de auditoria; definir roles de leitura e execução. Privilégios do dono e grants diretos exigem revisão. Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'Política PostgreSQL aprovada: olius_auditor SELECT; sem escrita direta pelos grupos reader, auditor, catalog_editor ou pela conta da API. Produção dos logs pelo mecanismo de auditoria autorizado. olius_owner administra a estrutura e conserva poderes de proprietário.DEFINED indica política documentada, não implantação. A view identifica roles com privilégio de dados em access_status; grants e memberships precisam de implantação própria.'),
('billing_charge', 'Pendente definir matriz completa de leitura, escrita e escopo por perfil/role. Perfil da API não equivale a role PostgreSQL. Este texto não concede permissões.', 'Política PostgreSQL aprovada: olius_owner administra o objeto. olius_reader sem acesso à tabela inteira por padrão. olius_auditor e olius_catalog_editor sem concessão adicional nesta tabela. olius_api recebe apenas os privilégios necessários às operações autorizadas; concessões exatas devem ser fechadas com as assinaturas das rotinas e consultas da API. Sem DELETE livre para fatos operacionais/financeiros; sem escrita livre em saldos. DEFINED indica política documentada, não implantação. A view identifica roles com privilégio de dados em access_status; grants e memberships precisam de implantação própria.'),
