UPDATE data_catalog_table d
SET access_policy = p.approved_policy, access_status = 'DEFINED'
FROM policies p
WHERE d.schema_name = current_schema() AND d.table_name = p.table_name
  AND d.access_policy = p.previous_policy;

-- Tabelas futuras são descobertas, sem inventar sua finalidade ou acesso.
INSERT INTO data_catalog_table
    (schema_name, table_name, domain_name, description, business_rules, access_policy, source_reference)
SELECT n.nspname, c.relname, 'Pendente de classificação',
       COALESCE(NULLIF(btrim(pg_catalog.obj_description(c.oid, 'pg_class')), ''), 'Pendente descrever a finalidade da tabela.'),
       'Pendente revisão das regras de negócio.', 'Pendente definir matriz de acesso.',
       'Descoberta no catálogo PostgreSQL; requer revisão humana'
FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
WHERE n.nspname = current_schema() AND c.relkind IN ('r', 'p')
  AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_depend dep
                  WHERE dep.classid = 'pg_class'::regclass AND dep.objid = c.oid AND dep.deptype = 'e')
ON CONFLICT (schema_name, table_name) DO NOTHING;

