INSERT INTO data_catalog_column
    (table_catalog_id, column_name, description, business_rules, access_policy, documentation_status, source_reference)
SELECT d.id, s.column_name, s.description, s.business_rules, s.access_policy, s.documentation_status, s.source_reference
FROM seed s JOIN data_catalog_table d ON d.schema_name = current_schema() AND d.table_name = s.table_name
JOIN pg_catalog.pg_namespace n ON n.nspname = d.schema_name
JOIN pg_catalog.pg_class c ON c.relnamespace = n.oid AND c.relname = d.table_name AND c.relkind IN ('r','p')
JOIN pg_catalog.pg_attribute a ON a.attrelid = c.oid AND a.attname = s.column_name AND a.attnum > 0 AND NOT a.attisdropped
ON CONFLICT (table_catalog_id, column_name) DO NOTHING;

-- Novas colunas recebem marcador PENDING; não serão apresentadas como documentadas.
INSERT INTO data_catalog_column
    (table_catalog_id, column_name, description, documentation_status, source_reference)
SELECT d.id, a.attname,
       COALESCE(NULLIF(btrim(pg_catalog.col_description(c.oid, a.attnum)), ''), 'Pendente descrever o significado da coluna.'),
       'PENDING', 'Descoberta no catálogo PostgreSQL; requer revisão humana'
FROM data_catalog_table d
JOIN pg_catalog.pg_namespace n ON n.nspname = d.schema_name
JOIN pg_catalog.pg_class c ON c.relnamespace = n.oid AND c.relname = d.table_name AND c.relkind IN ('r','p')
JOIN pg_catalog.pg_attribute a ON a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped
WHERE d.schema_name = current_schema()
ON CONFLICT (table_catalog_id, column_name) DO NOTHING;

-- Atualiza apenas a referência textual à apresentação antiga da view.
UPDATE data_catalog_table
SET access_policy = replace(access_policy, 'Privilégios reais são mostrados em role_permissions; grants e memberships precisam de implantação própria.', 'A view identifica roles com privilégio de dados em access_status; grants e memberships precisam de implantação própria.')
WHERE position('Privilégios reais são mostrados em role_permissions; grants e memberships precisam de implantação própria.' IN access_policy) > 0;

-- Revisão das sessões/idempotência de outubro de 2026. Não sobrescreve
-- descrições revisadas manualmente; atualiza somente descobertas PENDING.
WITH reviewed(table_name, domain_name, description, business_rules) AS (VALUES
('auth_session','Autenticação e sessões','Sessão independente por dispositivo para um usuário do OLIUS.','Validade exige usuário ativo, ausência de revogação e prazo vigente. Rotação renova a inatividade; logout, inativação e reutilização revogam a sessão. Não contém JWT.'),
('auth_refresh_token','Autenticação e sessões','Gerações de hashes de refresh tokens emitidos pela Core.','SHA-256 de 32 bytes; geração única por sessão, hash globalmente único e no máximo um token não consumido. Consumo é irreversível e registros são preservados para detectar reutilização.'),
('auth_session_log','Auditoria','Snapshots das alterações de sessões, sem hashes ou tokens.','Trigger dedicada grava snapshots na mesma transação. USER exige autor; SYSTEM não possui autor. Motorista não participa da auditoria de autenticação.')
)
UPDATE data_catalog_table d SET domain_name=r.domain_name, description=r.description,
    business_rules=r.business_rules, source_reference='01 a 05 principais; AUTH_SESSIONS.md — revisão 2026-10-06'
FROM reviewed r WHERE d.schema_name=current_schema() AND d.table_name=r.table_name
    AND d.domain_name='Pendente de classificação';

