UPDATE data_catalog_column dc SET description=r.description, documentation_status='DOCUMENTED',
    source_reference='01 a 05 principais — revisão 2026-10-06'
FROM reviewed r, data_catalog_table d
WHERE d.schema_name=current_schema() AND d.table_name=r.table_name
    AND dc.table_catalog_id=d.id AND dc.column_name=r.column_name
    AND dc.documentation_status='PENDING';

-- Atualizações de frases exatas da versão anterior, preservando os demais textos.
UPDATE data_catalog_table SET business_rules=replace(business_rules,
    'Produção dos retratos depende das futuras triggers;',
    'Produção dos retratos pelas triggers de auditoria do script 05;')
WHERE schema_name=current_schema();
UPDATE data_catalog_table SET business_rules=replace(business_rules,
    'Coerência de is_pev com a aprovação do PEV exige automação ainda não implementada nos três scripts.',
    'Coerência de is_pev com a aprovação do PEV é mantida pela trigger do script 05.')
WHERE schema_name=current_schema() AND table_name='establishment';

-- Matriz atual versionada: só substitui política gerada anteriormente por esta
