UPDATE data_catalog_table d SET access_policy=r.policy, access_status='DEFINED'
FROM reviewed r WHERE d.schema_name=current_schema() AND d.table_name=r.table_name
AND d.access_policy=r.previous_policy;

UPDATE data_catalog_column SET access_policy=replace(access_policy,
    'Matriz de leitura ainda pendente.',
    'Leitores sem acesso a este campo; consultar a política da tabela e os scripts 06/07.')
WHERE access_policy LIKE '%Matriz de leitura ainda pendente.%';

UPDATE data_catalog_role SET description='Papel NOLOGIN da Core API: SELECT nos quatro catálogos de referência e EXECUTE nas cinco funções de autenticação; sem DML direto nas sessões. Demais acessos de negócio ainda exigem concessões revisadas.' WHERE role_name='olius_api' AND description='Conta técnica da aplicação: consultas necessárias, alterações cadastrais limitadas e execução de rotinas autorizadas; sem propriedade dos objetos ou escrita livre em saldos e logs. Lista exata de concessões depende das rotinas.';
UPDATE data_catalog_role SET description='Papel NOLOGIN de Pedro/Caio. Proprietário dos objetos comuns listados no script 06, com manutenção de estrutura e dados. Funções privilegiadas de autenticação permanecem com olius_auth_owner. Não administra o servidor nem cria contas.' WHERE role_name='olius_owner' AND description='Proprietário técnico dos objetos do OLIUS; responsável pela implantação e alteração estrutural. Não é a conta da API. O nome por si só não transfere propriedade.';
-- Atualiza somente textos gerados conhecidos; preserva descrições humanas.
UPDATE data_catalog_table SET access_policy=replace(access_policy,
    'olius_api recebe apenas os privilégios necessários às operações autorizadas; concessões exatas devem ser fechadas com as assinaturas das rotinas e consultas da API.','olius_api consulta dados de negócio; alterações diretas são restritas por coluna e operações derivadas usam EXECUTE. Matriz exata: access_control/01_roles.sql e API_DATABASE_CONTRACT.md.') WHERE position('olius_api recebe apenas os privilégios necessários às operações autorizadas; concessões exatas devem ser fechadas com as assinaturas das rotinas e consultas da API.' IN access_policy)>0;
UPDATE data_catalog_role SET description='Papel NOLOGIN da Core: consultas de negócio, escrita limitada por coluna e EXECUTE nas rotinas públicas; sem acesso direto a sessões, refresh tokens ou logs. Contrato: access_control/01_roles.sql e API_DATABASE_CONTRACT.md.'
WHERE role_name='olius_api' AND description='Papel NOLOGIN da Core API: SELECT nos quatro catálogos de referência e EXECUTE nas cinco funções de autenticação; sem DML direto nas sessões. Demais acessos de negócio ainda exigem concessões revisadas.';

COMMIT;
